import{az as t,P as a,Q as l,aQ as n}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const F=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"css/概念/atomic.md","filePath":"css/概念/atomic.md","lastUpdated":1785249401000}'),o={name:"css/概念/atomic.md"};function e(r,s,p,c,i,d){return a(),l("div",null,[...s[0]||(s[0]=[n(`<h2 id="atomic-css-原子化-css" tabindex="-1">Atomic CSS（原子化 CSS） <a class="header-anchor" href="#atomic-css-原子化-css" aria-label="Permalink to “Atomic CSS（原子化 CSS）”">​</a></h2><p>Atomic CSS 即&quot;原子化 CSS&quot;，是一种将样式拆解到<strong>最小粒度</strong>的写法：每个类名只承担一个单一的 CSS 声明（或一组高度内聚的声明）。例如 <code>.text-center { text-align: center; }</code>、<code>.mt-4 { margin-top: 1rem; }</code>。通过在 HTML 中组合多个原子类，即可拼出完整样式，而无需为每个组件单独编写 CSS。</p><p>参考链接：<a href="https://acss.io/" target="_blank" rel="noreferrer">https://acss.io/</a></p><h2 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to “核心思想”">​</a></h2><p>原子化 CSS 的核心思想是 <strong>&quot;每个类只做一件事&quot;</strong>（Single Responsibility Principle 应用于样式）。它不再以&quot;组件&quot;为单位书写 CSS，而是以&quot;属性&quot;为单位：</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">&lt;!-- 传统写法：在 CSS 中定义 .card --&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">div</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">card</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">内容</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">&lt;!-- 原子化写法：在 HTML 中组合原子类 --&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">div</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">bg-white border border-gray-200 rounded-lg p-4</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">内容</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span></code></pre></div><p>这种思路有几个直接的好处：</p><ol><li><strong>不再需要为命名而苦恼</strong>：类名即样式，所见即所得。</li><li><strong>CSS 体积可控</strong>：随着项目增长，新增样式几乎不增加 CSS 体积（原子类集合趋于收敛）。</li><li><strong>删除即清理</strong>：删掉 HTML 上的类，对应样式自然失效，没有&quot;死 CSS&quot;。</li></ol><h2 id="与-utility-first-css-的关系" tabindex="-1">与 Utility-First CSS 的关系 <a class="header-anchor" href="#与-utility-first-css-的关系" aria-label="Permalink to “与 Utility-First CSS 的关系”">​</a></h2><p>&quot;原子化 CSS&quot; 与 &quot;Utility-First CSS&quot; 经常被混用，但二者侧重略有不同：</p><table tabindex="0"><thead><tr><th>概念</th><th>侧重</th><th>说明</th></tr></thead><tbody><tr><td>Atomic CSS</td><td>类的粒度</td><td>强调每个类只做一件事</td></tr><tr><td>Utility-First CSS</td><td>使用方式</td><td>强调优先使用工具类而非自定义类</td></tr></tbody></table><p><strong>Utility-First CSS 是 Atomic CSS 的一种实践策略</strong>：它鼓励开发者先用现成的工具类拼装，只有当工具类无法满足时才下沉到自定义 CSS。Tailwind 就是这一理念的典型代表，其官网明确提出 &quot;A utility-first CSS framework&quot;。</p><h2 id="优缺点分析" tabindex="-1">优缺点分析 <a class="header-anchor" href="#优缺点分析" aria-label="Permalink to “优缺点分析”">​</a></h2><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h3><ul><li><strong>CSS 体积收敛</strong>：项目越大，原子化带来的体积优势越明显，因为类名可无限复用。</li><li><strong>无死代码</strong>：HTML 中移除类即可移除样式，无需手动清理 CSS。</li><li><strong>样式与结构同处一地</strong>：修改某个元素的样式时，无需在 HTML 和 CSS 之间跳转。</li><li><strong>一致性高</strong>：基于设计系统约束（spacing scale、color palette），视觉风格天然统一。</li><li><strong>无需命名</strong>：消除&quot;起类名&quot;的心智负担。</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h3><ul><li><strong>HTML 膨胀</strong>：类名冗长，可读性下降，例如 <code>class=&quot;flex items-center justify-between px-4 py-2 text-sm font-medium&quot;</code>。</li><li><strong>学习曲线</strong>：需要记忆大量工具类及其缩写。</li><li><strong>抽象缺失</strong>：难以表达&quot;这是一个按钮组件&quot;的语义，复用需借助组件化封装。</li><li><strong>调试不便</strong>：DevTools 中样式来源分散在多个类上，排查需理清覆盖顺序。</li><li><strong>极端样式难表达</strong>：复杂动画、特殊伪元素结构仍需自定义 CSS。</li></ul><h2 id="代表框架" tabindex="-1">代表框架 <a class="header-anchor" href="#代表框架" aria-label="Permalink to “代表框架”">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>特点</th><th>风格</th></tr></thead><tbody><tr><td>Tailwind CSS</td><td>最流行，生态完善，JIT 按需生成</td><td>Utility-First</td></tr><tr><td>UnoCSS</td><td>引擎化、可编程、超快，按需生成</td><td>原子化引擎</td></tr><tr><td>Tachyons</td><td>早期原子化框架，固定类名集合</td><td>原子化</td></tr><tr><td>Windi CSS</td><td>Tailwind 兼容替代（已停止维护）</td><td>Utility-First</td></tr><tr><td>Atomizer</td><td>ACSS 官方实现，类名即 CSS</td><td>原子化</td></tr></tbody></table><p>以 UnoCSS 为例，可通过规则定义自定义原子类：</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">// uno.config.ts</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#89DDFF;"> {</span><span style="color:#BABED8;"> defineConfig</span><span style="color:#89DDFF;"> }</span><span style="color:#89DDFF;font-style:italic;"> from</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">unocss</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#89DDFF;font-style:italic;"> default</span><span style="color:#82AAFF;"> defineConfig</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  rules</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> [</span></span>
<span class="line"><span style="color:#BABED8;">    [</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">m-1</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> {</span><span style="color:#F07178;"> margin</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">0.25rem</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> }</span><span style="color:#BABED8;">]</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;">    [</span><span style="color:#89DDFF;">/</span><span style="color:#89DDFF;font-style:italic;">^</span><span style="color:#C3E88D;">p-</span><span style="color:#89DDFF;">(</span><span style="color:#C3E88D;">\\d</span><span style="color:#89DDFF;">+)</span><span style="color:#89DDFF;font-style:italic;">$</span><span style="color:#89DDFF;">/</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> ([,</span><span style="color:#BABED8;font-style:italic;"> d</span><span style="color:#89DDFF;">])</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#BABED8;"> (</span><span style="color:#89DDFF;">{</span><span style="color:#F07178;"> padding</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> \`\${</span><span style="color:#BABED8;">d </span><span style="color:#89DDFF;">/</span><span style="color:#F78C6C;"> 4</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">rem</span><span style="color:#89DDFF;">\`</span><span style="color:#89DDFF;"> }</span><span style="color:#BABED8;">)]</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;">  ]</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span></code></pre></div><h2 id="与传统-bem-oocss-的对比" tabindex="-1">与传统 BEM / OOCSS 的对比 <a class="header-anchor" href="#与传统-bem-oocss-的对比" aria-label="Permalink to “与传统 BEM / OOCSS 的对比”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Atomic CSS</th><th>BEM</th><th>OOCSS</th></tr></thead><tbody><tr><td>组织单位</td><td>属性 / 声明</td><td>块-元素-修饰符</td><td>结构与皮肤分离</td></tr><tr><td>命名方式</td><td>工具类缩写</td><td><code>.block__elem--mod</code></td><td>语义化类名</td></tr><tr><td>CSS 体积</td><td>收敛，几乎不增长</td><td>随组件线性增长</td><td>中等</td></tr><tr><td>HTML 可读性</td><td>较差，类名冗长</td><td>较好，语义清晰</td><td>较好</td></tr><tr><td>复用方式</td><td>类名组合</td><td>复制结构 + 类名</td><td>抽象对象</td></tr><tr><td>适合场景</td><td>组件化框架、设计系统</td><td>传统多页面、团队协作</td><td>组件库</td></tr><tr><td>学习成本</td><td>中等（需记类名）</td><td>低</td><td>中</td></tr></tbody></table><p>关键差异在于：<strong>BEM/OOCSS 把样式写在 CSS 文件里</strong>，而 <strong>Atomic CSS 把样式&quot;写&quot;在 HTML 的 class 里</strong>。在组件化框架（React/Vue）中，原子类的&quot;丑陋&quot;可以被组件封装隐藏，从而兼得两者优势：</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">&lt;!-- Button.vue：内部使用原子类，对外只暴露语义化组件 --&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">template</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">button</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">inline-flex items-center px-4 py-2 rounded text-white bg-blue-500 hover:bg-blue-600</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">    &lt;</span><span style="color:#F07178;">slot</span><span style="color:#89DDFF;"> /&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;/</span><span style="color:#F07178;">button</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">template</span><span style="color:#89DDFF;">&gt;</span></span></code></pre></div><h2 id="何时使用原子化-css" tabindex="-1">何时使用原子化 CSS <a class="header-anchor" href="#何时使用原子化-css" aria-label="Permalink to “何时使用原子化 CSS”">​</a></h2><p>原子化 CSS 并非银弹，是否选用应结合项目特征判断。</p><p><strong>适合的场景：</strong></p><ul><li>基于 React/Vue 等组件化框架的中大型项目。</li><li>有明确设计系统（design tokens）需要落地。</li><li>团队希望减少 CSS 维护成本、追求快速迭代。</li><li>需要主题切换、深色模式等动态样式。</li></ul><p><strong>不太适合的场景：</strong></p><ul><li>内容驱动的传统多页面网站（HTML 中大量重复原子类，难以维护）。</li><li>没有组件化封装的纯静态页面。</li><li>高度定制的视觉风格、不遵循统一设计规范的场景。</li></ul><p>一个简单的判断标准：<strong>如果你的 HTML 是由组件渲染出来的，原子类被封装在组件内部，那么 Atomic CSS 的缺点几乎可以忽略；反之则需谨慎。</strong></p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://acss.io/" target="_blank" rel="noreferrer">Atomic CSS 官方网站</a></li><li><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a></li><li><a href="https://unocss.dev/" target="_blank" rel="noreferrer">UnoCSS</a></li><li><a href="https://tachyons.io/" target="_blank" rel="noreferrer">Tachyons</a></li><li><a href="https://acss.io/guides/scope.html" target="_blank" rel="noreferrer">Why Atomic CSS</a></li></ul>`,34)])])}const h=t(o,[["render",e]]);export{F as __pageData,h as default};
